# --- stan_core.py: shared Stan-equivalent warmup and NUTS kernel --------------------------------
# This block is the shared part of every Harbor reference file. scripts/sync_harbor_tests.py
# writes harbor/tasks/<task>/tests/reference.py as `stan_core.py` + one lane tail
# (lane_nuts.py, lane_a1_metric.py, lane_a4_transport.py). The worker sandbox lets a submission
# read only its own file, so each reference must be one self-contained file.
"""Stan-equivalent reference sampler for the apin Harbor verifier (verifier side only).

Port of Stan 2.37 (`stan/src/stan/mcmc/hmc/nuts/base_nuts.hpp`, `base_hmc.hpp`,
`hmc/integrators/base_leapfrog.hpp`, `stepsize_adaptation.hpp`, `windowed_adaptation.hpp`,
`var_adaptation.hpp`, `adapt_diag_e_nuts.hpp`, `services/util/run_adaptive_sampler.hpp`) to the
harness `adapt()` / `transition()` interface, with CmdStan's defaults.

Identical to Stan (same algorithm, same constants, same order of operations):
  - Multinomial NUTS with the generalized no-U-turn criterion on sharp momenta (`p_sharp =
    M^{-1} p`), including Stan's two extra checks across the merged subtrees; biased progressive
    sampling between the old tree and the new subtree, uniform progressive sampling inside a
    subtree; divergence when H - H0 > 1000; max tree depth 10; leapfrog integrator.
  - Diagonal Euclidean metric: p ~ N(0, M), kinetic energy 0.5 p' M^{-1} p.
  - Step-size search at the start of warmup and after every metric update (`init_stepsize`):
    start from the current nominal step size, one leapfrog step with fresh momentum, double or halve
    until the acceptance crosses 0.8.
  - Dual averaging: delta = 0.8, gamma = 0.05, kappa = 0.75, t0 = 10, mu = log(10 eps), restarted
    after each metric update; the final step size is exp(x_bar).
  - Windowed diagonal variance adaptation: Welford sample variance over each window, regularized as
    (n / (n + 5)) var + 1e-3 (5 / (n + 5)); window doubling and stretching as in
    `compute_next_window`. Warmup shorter than init_buffer + window + term_buffer (75 + 25 + 50)
    is rescaled to 15% / 75% / 10% as Stan does; num_warmup = budget.draws (100 in Tier 1 gives
    init_buffer 15, one 75-draw window, term_buffer 10). Below 20 warmup draws there is no metric
    adaptation, as in Stan.
  - Initial point: uniform(-2, 2) on every coordinate, up to 100 tries for a finite log density
    and gradient; initial nominal step size 1; step-size jitter 0 (CmdStan's default, so
    `sample_stepsize` returns the nominal step size; STEPSIZE_JITTER switches Stan's jitter on).
  - accept_stat = mean over all leapfrog states of min(1, exp(H0 - H)).

Not identical to Stan:
  - Short-warmup windows. Stan 2.37 (and 2.39) has a bug: when warmup is too short for the
    default buffers, `windowed_adaptation::set_window_params` computes the 15/75/10 windows but
    returns without `restart()`, so the end of the first window stays at its constructor value and
    the metric is never updated (CmdStan with num_warmup=100 reports a unit inverse metric). This
    reference follows the documented behaviour instead (the windows Stan prints are used). That is
    exactly what CmdStan does when the same windows are passed explicitly
    (`adapt init_buffer=15 window=75 term_buffer=10` for 100 warmup draws).
    SHORT_WARMUP_RESTART = False reproduces the bug.
  - Gradient caching. Stan recomputes the log density and gradient at the current point at the
    start of every transition and every step-size search (`hamiltonian.init`). Inside adapt() this
    port reuses the value it already holds: same numbers, one gradient fewer per warmup draw. The
    sampling transition() does recompute it, because the chain carries only the position.
  - Random numbers come from the numpy Generator the harness passes in, not Stan's boost
    ecuyer1988, so draws are not bit-identical to CmdStan; the comparisons are statistical.
  - Failure handling. Stan treats a throwing log density as infinite energy; here a non-finite log
    density or gradient is infinite energy (a divergence). If no finite initial point is found in
    100 tries the reference uses the origin instead of aborting.
  - One chain. CmdStan's default is 4 chains; the harness runs adapt() once per target.
  - Lane A1 and A4 references hand Stan's adapted step size and diagonal metric to the judge's
    fixed HMC kernel, so only the warmup is Stan's; see the lane tail for details.
"""

from __future__ import annotations

import math

import numpy as np

STAN_VERSION = "2.37.0"
MAX_TREE_DEPTH = 10
MAX_DELTA_H = 1000.0
DELTA = 0.8
GAMMA = 0.05
KAPPA = 0.75
T0 = 10.0
INIT_STEPSIZE = 1.0
STEPSIZE_JITTER = 0.0
INIT_RADIUS = 2.0
INIT_TRIES = 100
INIT_BUFFER = 75
TERM_BUFFER = 50
BASE_WINDOW = 25
SHORT_WARMUP_RESTART = True
_UINT_MAX = 2**32 - 1


class _Point:
    """Stan's ps_point for a diagonal Euclidean metric: position, momentum, log density, gradient."""

    __slots__ = ("g", "lp", "p", "q")

    def __init__(self, q, p, lp, g):
        self.q, self.p, self.lp, self.g = q, p, lp, g

    def copy(self):
        return _Point(self.q, self.p, self.lp, self.g)


def _finite(lp, g) -> bool:
    return math.isfinite(lp) and bool(np.all(np.isfinite(g)))


def _hamiltonian(z: _Point, inv_m: np.ndarray) -> float:
    if not _finite(z.lp, z.g):
        return math.inf
    h = -z.lp + 0.5 * float(np.dot(z.p, inv_m * z.p))
    return math.inf if math.isnan(h) else h


def _leapfrog(z: _Point, oracle, inv_m: np.ndarray, eps: float) -> _Point:
    """Stan's expl_leapfrog: half kick, drift, gradient, half kick (dphi_dq = -grad log p)."""
    p = z.p + 0.5 * eps * z.g
    q = z.q + eps * (inv_m * p)
    lp, g = oracle.log_density_gradient(q)
    lp = float(lp)
    g = np.asarray(g, dtype=np.float64)
    if _finite(lp, g):
        p = p + 0.5 * eps * g
    return _Point(q, p, lp, g)


def _log_sum_exp(a: float, b: float) -> float:
    if a == -math.inf:
        return b
    if b == -math.inf:
        return a
    m = max(a, b)
    return m + math.log(math.exp(a - m) + math.exp(b - m))


def _criterion(p_sharp_minus: np.ndarray, p_sharp_plus: np.ndarray, rho: np.ndarray) -> bool:
    return float(np.dot(p_sharp_plus, rho)) > 0.0 and float(np.dot(p_sharp_minus, rho)) > 0.0


class _Trajectory:
    """One NUTS transition's mutable state: the moving point, H0, leapfrog and divergence counts."""

    def __init__(self, z: _Point, oracle, inv_m: np.ndarray, eps: float, rng):
        self.z = z
        self.oracle = oracle
        self.inv_m = inv_m
        self.eps = eps
        self.rng = rng
        self.h0 = _hamiltonian(z, inv_m)
        self.n_leapfrog = 0
        self.sum_metro_prob = 0.0
        self.divergent = False
        self.depth = 0

    def build_tree(self, depth: int, sign: float):
        """Port of base_nuts::build_tree. Returns (valid, z_propose, p_sharp_beg, p_sharp_end, rho,
        p_beg, p_end, log_sum_weight) for a subtree of 2**depth leapfrog steps in direction `sign`."""
        if depth == 0:
            self.z = _leapfrog(self.z, self.oracle, self.inv_m, sign * self.eps)
            self.n_leapfrog += 1
            h = _hamiltonian(self.z, self.inv_m)
            if h - self.h0 > MAX_DELTA_H:
                self.divergent = True
            lsw = self.h0 - h
            self.sum_metro_prob += 1.0 if self.h0 - h > 0 else math.exp(self.h0 - h)
            p_sharp = self.inv_m * self.z.p
            return (not self.divergent, self.z, p_sharp, p_sharp, self.z.p.copy(),
                    self.z.p, self.z.p, lsw)

        ok, z_prop, ps_beg, ps_init_end, rho_init, p_beg, p_init_end, lsw_init = self.build_tree(depth - 1, sign)
        if not ok:
            return False, None, None, None, None, None, None, -math.inf
        ok, z_prop_final, ps_final_beg, ps_end, rho_final, p_final_beg, p_end, lsw_final = self.build_tree(
            depth - 1, sign)
        if not ok:
            return False, None, None, None, None, None, None, -math.inf

        lsw_subtree = _log_sum_exp(lsw_init, lsw_final)
        # Uniform progressive sampling inside the subtree (the uniform is drawn only when needed).
        if lsw_final > lsw_subtree or self.rng.uniform() < math.exp(lsw_final - lsw_subtree):
            z_prop = z_prop_final

        rho_subtree = rho_init + rho_final
        persist = _criterion(ps_beg, ps_end, rho_subtree)
        persist = persist and _criterion(ps_beg, ps_final_beg, rho_init + p_final_beg)
        persist = persist and _criterion(ps_init_end, ps_end, rho_final + p_init_end)
        return persist, z_prop, ps_beg, ps_end, rho_subtree, p_beg, p_end, lsw_subtree

    def run(self, max_depth: int = MAX_TREE_DEPTH, directions=None) -> _Point:
        """Port of base_nuts::transition after momentum sampling. `directions` (+1/-1 per depth)
        replaces the coin flips; tests use it to rebuild the same orbit from another start."""
        z0 = self.z
        z_fwd, z_bck = z0, z0
        z_sample = z0
        p_sharp0 = self.inv_m * z0.p
        p_fwd_fwd = p_fwd_bck = p_bck_fwd = p_bck_bck = z0.p
        ps_fwd_fwd = ps_fwd_bck = ps_bck_fwd = ps_bck_bck = p_sharp0
        rho = z0.p.copy()
        log_sum_weight = 0.0
        self.depth = 0
        while self.depth < max_depth:
            if directions is not None:
                forward = directions[self.depth] > 0
            else:
                forward = self.rng.uniform() > 0.5
            if forward:
                self.z = z_fwd
                rho_bck = rho
                p_bck_fwd, ps_bck_fwd = p_fwd_fwd, ps_fwd_fwd
                ok, z_prop, ps_fwd_bck, ps_fwd_fwd, rho_fwd, p_fwd_bck, p_fwd_fwd, lsw_sub = self.build_tree(
                    self.depth, 1.0)
                z_fwd = self.z
            else:
                self.z = z_bck
                rho_fwd = rho
                p_fwd_bck, ps_fwd_bck = p_bck_bck, ps_bck_bck
                ok, z_prop, ps_bck_fwd, ps_bck_bck, rho_bck, p_bck_fwd, p_bck_bck, lsw_sub = self.build_tree(
                    self.depth, -1.0)
                z_bck = self.z
            if not ok:
                break
            self.depth += 1
            # Biased progressive sampling between the old tree and the new subtree.
            if lsw_sub > log_sum_weight or self.rng.uniform() < math.exp(lsw_sub - log_sum_weight):
                z_sample = z_prop
            log_sum_weight = _log_sum_exp(log_sum_weight, lsw_sub)
            rho = rho_bck + rho_fwd
            persist = _criterion(ps_bck_bck, ps_fwd_fwd, rho)
            persist = persist and _criterion(ps_bck_bck, ps_fwd_bck, rho_bck + p_fwd_bck)
            persist = persist and _criterion(ps_bck_fwd, ps_fwd_fwd, rho_fwd + p_bck_fwd)
            if not persist:
                break
        self.log_sum_weight = log_sum_weight
        return z_sample


def _sample_momentum(inv_m: np.ndarray, rng) -> np.ndarray:
    return rng.standard_normal(inv_m.size) / np.sqrt(inv_m)


def _sample_stepsize(nom_eps: float, rng) -> float:
    if STEPSIZE_JITTER:
        return nom_eps * (1.0 + STEPSIZE_JITTER * (2.0 * rng.uniform() - 1.0))
    return nom_eps


def nuts_transition(q, lp, g, oracle, inv_m: np.ndarray, nom_eps: float, rng,
                    max_depth: int = MAX_TREE_DEPTH):
    """One Stan NUTS transition from (q, lp, g). Returns (point, accept_stat, trajectory)."""
    eps = _sample_stepsize(nom_eps, rng)
    z = _Point(q, _sample_momentum(inv_m, rng), lp, g)
    traj = _Trajectory(z, oracle, inv_m, eps, rng)
    z_sample = traj.run(max_depth)
    accept_stat = traj.sum_metro_prob / max(1, traj.n_leapfrog)
    return z_sample, accept_stat, traj


def init_stepsize(q, lp, g, oracle, inv_m: np.ndarray, nom_eps: float, rng) -> float:
    """Port of base_hmc::init_stepsize: double or halve until one-step acceptance crosses 0.8."""
    if nom_eps == 0 or nom_eps > 1e7 or math.isnan(nom_eps):
        return nom_eps
    log_08 = math.log(0.8)

    def delta_h(eps: float) -> float:
        z = _Point(q, _sample_momentum(inv_m, rng), lp, g)
        h0 = _hamiltonian(z, inv_m)
        h = _hamiltonian(_leapfrog(z, oracle, inv_m, eps), inv_m)
        return h0 - h

    direction = 1 if delta_h(nom_eps) > log_08 else -1
    while True:
        dh = delta_h(nom_eps)
        if direction == 1 and not (dh > log_08):
            break
        if direction == -1 and not (dh < log_08):
            break
        nom_eps = 2.0 * nom_eps if direction == 1 else 0.5 * nom_eps
        if nom_eps > 1e7:
            raise RuntimeError("Posterior is improper. Please check your model.")
        if nom_eps == 0:
            raise RuntimeError("No acceptably small step size could be found.")
    return nom_eps


class _StepsizeAdaptation:
    """Port of stepsize_adaptation (Nesterov dual averaging of log step size)."""

    def __init__(self, mu: float):
        self.mu = mu
        self.restart()

    def restart(self) -> None:
        self.counter = 0.0
        self.s_bar = 0.0
        self.x_bar = 0.0

    def learn(self, adapt_stat: float) -> float:
        self.counter += 1.0
        adapt_stat = min(1.0, adapt_stat)
        eta = 1.0 / (self.counter + T0)
        self.s_bar = (1.0 - eta) * self.s_bar + eta * (DELTA - adapt_stat)
        x = self.mu - self.s_bar * math.sqrt(self.counter) / GAMMA
        x_eta = self.counter ** (-KAPPA)
        self.x_bar = (1.0 - x_eta) * self.x_bar + x_eta * x
        return math.exp(x)

    def complete(self, eps: float) -> float:
        return math.exp(self.x_bar) if self.counter > 0 else eps


class _VarAdaptation:
    """Port of windowed_adaptation + var_adaptation with a Welford variance estimator."""

    def __init__(self, dim: int, num_warmup: int):
        self.dim = dim
        self.num_warmup = 0
        self.init_buffer = 0
        self.term_buffer = 0
        self.base_window = 0
        self._restart()
        self._reset_estimator()
        self.windows: list[tuple[int, int]] = []
        self._window_start = None
        if num_warmup < 20:
            return
        if INIT_BUFFER + BASE_WINDOW + TERM_BUFFER > num_warmup:
            self.num_warmup = num_warmup
            self.init_buffer = int(0.15 * num_warmup)
            self.term_buffer = int(0.10 * num_warmup)
            self.base_window = num_warmup - (self.init_buffer + self.term_buffer)
            if SHORT_WARMUP_RESTART:
                self._restart()
            return
        self.num_warmup = num_warmup
        self.init_buffer = INIT_BUFFER
        self.term_buffer = TERM_BUFFER
        self.base_window = BASE_WINDOW
        self._restart()

    def _restart(self) -> None:
        self.counter = 0
        self.window_size = self.base_window
        self.next_window = (self.init_buffer + self.window_size - 1) & _UINT_MAX

    def _reset_estimator(self) -> None:
        self.n = 0
        self.mean = np.zeros(self.dim)
        self.m2 = np.zeros(self.dim)

    def _in_window(self) -> bool:
        return (self.counter >= self.init_buffer
                and self.counter < self.num_warmup - self.term_buffer
                and self.counter != self.num_warmup)

    def _end_window(self) -> bool:
        return self.counter == self.next_window and self.counter != self.num_warmup

    def _compute_next_window(self) -> None:
        last = self.num_warmup - self.term_buffer - 1
        if self.next_window == last:
            return
        self.window_size *= 2
        self.next_window = self.counter + self.window_size
        if self.next_window == last:
            return
        if self.next_window + 2 * self.window_size >= self.num_warmup - self.term_buffer:
            self.next_window = last

    def learn(self, q: np.ndarray):
        """Returns the new regularized variance when a window closes, else None."""
        if self._in_window():
            if self.n == 0:
                self._window_start = self.counter
            self.n += 1
            delta = q - self.mean
            self.mean = self.mean + delta / self.n
            self.m2 = self.m2 + (q - self.mean) * delta
        if self._end_window():
            self._compute_next_window()
            n = float(self.n)
            var = self.m2 / (n - 1.0) if self.n > 1 else np.zeros(self.dim)
            var = (n / (n + 5.0)) * var + 1e-3 * (5.0 / (n + 5.0)) * np.ones(self.dim)
            if not np.all(np.isfinite(var)):
                raise RuntimeError("Numerical overflow in metric adaptation.")
            self.windows.append((int(self._window_start), int(self.counter)))
            self.last_window_mean = self.mean.copy()
            self._reset_estimator()
            self.counter += 1
            return var
        self.counter += 1
        return None


def stan_init(oracle, rng):
    """Stan's random initialization: uniform(-2, 2), up to 100 tries for finite lp and gradient."""
    for _ in range(INIT_TRIES):
        q = rng.uniform(-INIT_RADIUS, INIT_RADIUS, size=oracle.dim)
        lp, g = oracle.log_density_gradient(q)
        g = np.asarray(g, dtype=np.float64)
        if _finite(float(lp), g):
            return q, float(lp), g
    q = np.zeros(oracle.dim, dtype=np.float64)
    lp, g = oracle.log_density_gradient(q)
    return q, float(lp), np.asarray(g, dtype=np.float64)


def stan_warmup(oracle, num_warmup: int, rng, max_depth: int = MAX_TREE_DEPTH) -> dict:
    """Run Stan's adaptive warmup (adapt_diag_e_nuts + run_adaptive_sampler) for num_warmup draws.

    Returns the final position with its log density and gradient, the adapted step size, the
    diagonal inverse metric, the mean of the last metric window (None if no window closed), and
    warmup diagnostics."""
    dim = oracle.dim
    q, lp, g = stan_init(oracle, rng)
    inv_m = np.ones(dim, dtype=np.float64)
    nom_eps = INIT_STEPSIZE
    step = _StepsizeAdaptation(math.log(10.0 * nom_eps))
    var = _VarAdaptation(dim, num_warmup)
    nom_eps = init_stepsize(q, lp, g, oracle, inv_m, nom_eps, rng)
    depths: list[int] = []
    n_leapfrog = 0
    n_divergent = 0
    window_mean = None
    for _ in range(int(num_warmup)):
        z, accept_stat, traj = nuts_transition(q, lp, g, oracle, inv_m, nom_eps, rng, max_depth)
        q, lp, g = z.q, z.lp, z.g
        depths.append(traj.depth)
        n_leapfrog += traj.n_leapfrog
        n_divergent += int(traj.divergent)
        nom_eps = step.learn(accept_stat)
        new_var = var.learn(q)
        if new_var is not None:
            inv_m = new_var
            window_mean = var.last_window_mean
            nom_eps = init_stepsize(q, lp, g, oracle, inv_m, nom_eps, rng)
            step.mu = math.log(10.0 * nom_eps)
            step.restart()
    nom_eps = step.complete(nom_eps)
    return {
        "q": q, "lp": lp, "g": g, "eps": float(nom_eps), "inv_m": np.asarray(inv_m, dtype=np.float64),
        "window_mean": window_mean, "windows": list(var.windows), "depths": depths,
        "n_leapfrog": n_leapfrog, "n_divergent": n_divergent,
    }


# --- lane_a4_transport.py: lane A4 (the judge owns latent HMC; the submission owns the map) ------
# Appended to stan_core.py by scripts/sync_harbor_tests.py; not importable on its own.
#
# The map is T(z) = loc + scale * z with scale = sqrt(Stan's regularized window variance) and
# loc = the Welford mean of the same window. The A4 starting code is not this map: it fits loc and
# scale by median and MAD over its own fixed-path HMC warmup, so it could not be reused.
# Unit-metric leapfrog in z is the same integrator as leapfrog in theta with inverse metric
# scale**2, so Stan's step size carries over to the judge's latent kernel unchanged (loc does not
# affect the dynamics). What is not Stan: the judge's sampling kernel (jittered fixed-path HMC,
# `harness/judge.py::make_a4_transition`), as in lane A1. If no metric window closes (warmup under
# 20 draws) the map is the identity, as Stan's metric would be.
REFERENCE_NAME = "stan-windowed-diag-affine-2.37"
REFERENCE_LANES = ("A4",)


def forward(transport_tuning, z):
    z_arr = np.asarray(z, dtype=np.float64)
    scale = transport_tuning["scale"]
    return transport_tuning["loc"] + scale * z_arr, float(np.sum(np.log(scale)))


def pullback_grad(transport_tuning, z, grad_theta):
    return transport_tuning["scale"] * np.asarray(grad_theta, dtype=np.float64)


def inverse(transport_tuning, theta):
    return (np.asarray(theta, dtype=np.float64) - transport_tuning["loc"]) / transport_tuning["scale"]


def adapt_transport(oracle, budget, rng):
    """Stan's warmup; the affine map is fitted from its last metric window."""
    w = stan_warmup(oracle, int(budget.draws), rng)
    scale = np.sqrt(np.asarray(w["inv_m"], dtype=np.float64))
    loc = w["window_mean"] if w["window_mean"] is not None else np.zeros(oracle.dim)
    eps = float(min(10.0, max(1e-8, w["eps"])))  # the judge accepts eps in [1e-8, 10]
    tuning = {"eps": eps, "loc": np.asarray(loc, dtype=np.float64), "scale": scale}
    return tuning, np.asarray(w["q"], dtype=np.float64)
